(6391853, 947148, 126709, '<td valign="top">Nice photo.  Love the contrast and color.  Good luck.</td>', 'Nice photo.  Love the contrast and color.  Good luck.', '2011-04-20 22:31:59.000000', NULL, 1),
(6391854, 947059, 131377, '<td valign="top">Oh goodness. That cat really looks undernourished. And very sad. Wonderful shot.</td>', 'Oh goodness. That cat really looks undernourished. And very sad. Wonderful shot.', '2011-04-20 22:32:40.000000', NULL, 1),
(6391855, 947061, 126709, '<td valign="top">I like the water on glass.  Nice feel.  Good luck.</td>', 'I like the water on glass.  Nice feel.  Good luck.', '2011-04-20 22:32:51.000000', NULL, 1),
(6391856, 946900, 126709, '<td valign="top">Love the contrast but not a lot of sadness to me.  Good luck.</td>', 'Love the contrast but not a lot of sadness to me.  Good luck.', '2011-04-20 22:33:23.000000', NULL, 1),
(6391857, 947126, 126709, '<td valign="top">Don''t know about the title but I like the photo.  Good luck.</td>', 'Don''t know about the title but I like the photo.  Good luck.', '2011-04-20 22:33:54.000000', NULL, 1),
(6391858, 947059, 124256, '<td valign="top">Gorgeous shot, gorgeous cat!  I have trouble feeling sad as I am so taken by how cute that cat looks.</td>', 'Gorgeous shot, gorgeous cat!  I have trouble feeling sad as I am so taken by how cute that cat looks.', '2011-04-20 22:34:01.000000', NULL, 1),
