(6391860, 946594, 126709, '<td valign="top">I like the eyes.  Good luck.</td>', 'I like the eyes.  Good luck.', '2011-04-20 22:34:37.000000', NULL, 1),
(6391862, 946655, 124256, '<td valign="top">I like the focus, but as soon as I realize it''s the eyelash, I wish it was the corner of the eye.  Why I couldn''t tell you.</td>', 'I like the focus, but as soon as I realize it''s the eyelash, I wish it was the corner of the eye.  Why I couldn''t tell you.', '2011-04-20 22:35:02.000000', NULL, 1),
