(6391910, 947102, 73296, '<td valign="top">Nice capture shows true sadness</td>', 'Nice capture shows true sadness', '2011-04-20 23:40:55.000000', NULL, 1),
(6391988, 946546, 129315, '<td valign="top">Very nice composition and tones, it fits like it''s telling a story.</td>', 'Very nice composition and tones, it fits like it''s telling a story.', '2011-04-21 04:18:40.000000', NULL, 1),
